query:
UPDATE gallery_items SET 
  description = 'Commercial shot blasting of structural steel columns at a large industrial facility. Using iron silicate media, our team achieved a consistent Sa 2.5 near-white metal cleanliness grade across every column, with a sharp Rz 50–75 μm anchor profile ideal for the replacement coating system. The before image shows the heavily coated and corroded column surface; the after image shows the clean, profiled bare metal ready for the coating contractor.'
WHERE id = 60001;

UPDATE gallery_items SET 
  description = 'Shot blasting of concrete floors and steel columns within a large commercial warehouse during a major refurbishment project. The steel columns required full coating and rust removal to Sa 2.5 standard using iron silicate media, while the concrete floor areas were prepared to receive a new industrial floor coating system. Our mobile blasting equipment allowed us to work efficiently across the entire building footprint in a single mobilisation.'
WHERE id = 60002;

UPDATE gallery_items SET 
  description = 'Wide-area shot blasting of structural steelwork across a large commercial building, treating dozens of columns across the full building footprint. Iron silicate media was used throughout to deliver consistent Sa 2.5 cleanliness and the anchor profile required by the protective coating specification. The wide-angle images illustrate the dramatic transformation achieved across the full extent of the steelwork.'
WHERE id = 60003;

UPDATE gallery_items SET 
  description = 'Close-up detail of a structural steel column mid-blast, showing the transition between coated and freshly blasted bare metal. The image demonstrates the quality of the Sa 2.5 near-white metal finish achieved using iron silicate media: a clean, bright surface with the angular anchor profile required for long-term coating adhesion. This type of quality check was carried out on every column to confirm the specified cleanliness grade.'
WHERE id = 60004;

UPDATE gallery_items SET 
  description = 'Systematic shot blasting of structural steel columns and beams across multiple bays of a commercial building undergoing full refurbishment. Iron silicate media delivered the Sa 2.5 near-white metal standard specified for the new intumescent and protective coating system. The project was completed on programme, with all blast media recovered and the site left clean and ready for the coating contractor.'
WHERE id = 60005;

